def settle_pot(session_id, winning_seat_id, pot_pts, rake_option):
    rake = min(int(pot_pts * rake_option['rake_pct']), rake_option['rake_cap_pts'])
    pot_to_winner = pot_pts - rake
    operator_pid = get_system_setting('poker_rake_operator_account_id')
    with db_transaction():
        if operator_pid and rake > 0:
            _add_points(db, operator_pid, rake, label=f'poker_rake_session_{session_id}')
        winner_pid = get_seat_player_id(winning_seat_id)
        _add_points(db, winner_pid, pot_to_winner, label=f'poker_pot_win_session_{session_id}')
    return {'rake': rake, 'pot_awarded': pot_to_winner}
